1389	/* ---------- Taste filters: genre, subgenre, price ----------
1390	 * Three chips sharing one idiom: a dropdown listing every option with a grey
1391	 * count of how many of today's shows it would give you, and an "everything!"
1392	 * link beside the question that clears the filter. Price is the odd one out —
1393	 * a single either/or answer, so it gets a narrow "$" button and a tiny
1394	 * dropdown carrying just the current selection. */
1395	
1396	/* Build one checkbox option row: emoji (optional), label, grey count. */
1397	function facetOption(value, { icon, checked, count, onToggle }) {
1398	  const label = document.createElement("label");
1399	  label.className = "panel-option" + (count === 0 ? " is-empty" : "");
1400	  label.innerHTML = `
1401	    <input type="checkbox" value="${escapeHtml(value)}" ${checked ? "checked" : ""} />
1402	    <span>${icon ? `<span class="opt-ico" aria-hidden="true">${icon}</span> ` : ""}${escapeHtml(value)}</span>
1403	    <span class="opt-count" aria-label="${count} ${count === 1 ? "show" : "shows"}">${count}</span>`;
1404	  const input = label.querySelector("input");
1405	  input.addEventListener("change", () => onToggle(input.checked));
1406	  return label;
1407	}
1408	
1409	/* The pool a facet's per-option counts are measured against: the shows you
1410	 * could actually wander into — reachable in your travel window, not already
1411	 * started, and leaving time for your next commitment — with every filter
1412	 * applied *except* this facet's own. So a count answers "how many more could I
1413	 * catch if I ticked this", and the numbers add up against the heading above
1414	 * the filters rather than against the whole day's 3,800-show programme. */
1415	function facetPool(facet) {
1416	  return fittingShows(facet).map((o) => o.show);
1417	}
1418	
1419	/* How many shows in `pool` fall under each value of a facet. `values` pulls the
1420	 * facet's value(s) out of a show (a genre is one, subgenres are many). */
1421	function facetCounts(pool, values) {
1422	  const counts = new Map();
1423	  for (const show of pool) {
1424	    for (const v of values(show)) counts.set(v, (counts.get(v) || 0) + 1);
1425	  }
1426	  return counts;
1427	}
1428	
1429	function buildGenrePanel() {
1430	  const wrap = document.getElementById("genreOptions");
1431	  if (!wrap) return;
1432	  const counts = facetCounts(facetPool("genre"), (s) => [s.genre]);
1433	  wrap.innerHTML = "";
1434	  GENRES.forEach((genre) => {
1435	    wrap.appendChild(
1436	      facetOption(genre, {
1437	        icon: genreIcon(genre),
1438	        checked: state.selectedGenres.has(genre),
1439	        count: counts.get(genre) || 0,
1440	        onToggle: (on) => {
1441	          if (on) state.selectedGenres.add(genre);
1442	          else state.selectedGenres.delete(genre);
1443	          onTasteChange({ rebuildSubgenres: true });
1444	        },
1445	      })
1446	    );
1447	  });
1448	
1449	  const reset = document.getElementById("filterReset");
1450	  if (reset) {
1451	    reset.onclick = () => {
1452	      // Ticked everything already → the link is "nothing!", clearing the boxes
1453	      // so you can pick a few from a blank slate.
1454	      state.selectedGenres =
1455	        state.selectedGenres.size === GENRES.length ? new Set() : new Set(GENRES);
1456	      buildGenrePanel(); // re-render the checkboxes
1457	      onTasteChange({ rebuildSubgenres: true });
1458	    };
1459	  }
1460	  updateEverythingLinks();
1461	}
1462	
1463	/* The "everything!" links flip to "nothing!" once every box in their panel is
1464	 * ticked — at which point the useful move is to clear them and start picking.
1465	 * For genres the two ends are the same search (every show has one genre, so
1466	 * "all ticked" and "none ticked" both narrow nothing); for subgenres they
1467	 * differ by the ~2% of shows the festival tags with none, which "all ticked"
1468	 * excludes and "none ticked" keeps. The counts show that difference. */
1469	function updateEverythingLinks() {
1470	  const links = [
1471	    ["filterReset", state.selectedGenres.size > 0 && state.selectedGenres.size === GENRES.length],
1472	    ["subgenreReset", allSubgenresSelected()],
1473	  ];
1474	  for (const [id, all] of links) {
1475	    const link = document.getElementById(id);
1476	    if (!link) continue;
1477	    link.textContent = all ? "nothing!" : "everything!";
1478	    link.title = all ? "Untick every option" : "Tick every option";
1479	  }
1480	}
