      const n = counts.get(row.querySelector("input").value) || 0;
      const out = row.querySelector(".opt-count");
      out.textContent = String(n);
      out.setAttribute("aria-label", `${n} ${n === 1 ? "show" : "shows"}`);
      row.classList.toggle("is-empty", n === 0);
    });
  }
}

