import { chromium } from "playwright-core";

const proxy = process.env.HTTPS_PROXY || process.env.https_proxy;
const browser = await chromium.launch({
  executablePath: "/opt/pw-browsers/chromium/chrome-linux/chrome",
  args: ["--no-sandbox"],
  ...(proxy ? { proxy: { server: proxy } } : {}),
});
const ctx = await browser.newContext({
  ignoreHTTPSErrors: true,
  permissions: ["geolocation"],
  geolocation: { latitude: 55.9486, longitude: -3.1999 }, // Edinburgh Old Town
  locale: "en-GB",
});
const page = await ctx.newPage();
const errs = [];
page.on("pageerror", (e) => errs.push(String(e)));
await page.goto("http://localhost:8899/index.html", { waitUntil: "domcontentloaded" });
await page.waitForTimeout(4000);

const count = () => page.locator("#showsGrid > *").count();
const chip = (name) => page.locator(`[data-value="${name}"]`).textContent();
const openPanel = async (panel) => {
  const trigger = page.locator(`[data-panel="${panel}"]`);
  if ((await trigger.getAttribute("aria-expanded")) !== "true") await trigger.click();
  await page.waitForTimeout(200);
};
const resetText = (id) => page.locator(`#${id}`).textContent();
const clickReset = async (id) => {
  await page.locator(`#${id}`).click();
  await page.waitForTimeout(600);
};

const report = {};
report.errors = errs;
report.default = { shows: await count(), genre: await chip("genre"), sub: await chip("subgenre") };

// ---- genre: all ticked vs none ticked
await openPanel("genrePanel");
report.genreLinkBefore = await resetText("filterReset");
await clickReset("filterReset"); // -> everything ticked (default is Comedy only)
report.genreAll = {
  shows: await count(),
  chip: await chip("genre"),
  link: await resetText("filterReset"),
  boxes: await page.locator("#genreOptions input:checked").count(),
};
await clickReset("filterReset"); // -> nothing ticked
report.genreNone = {
  shows: await count(),
  chip: await chip("genre"),
  link: await resetText("filterReset"),
  boxes: await page.locator("#genreOptions input:checked").count(),
};

// ---- subgenre: all ticked vs none ticked (with every genre unticked = all shows)
await openPanel("subgenrePanel");
await clickReset("subgenreReset"); // tick every offered subgenre
report.subAll = {
  shows: await count(),
  chip: await chip("subgenre"),
  link: await resetText("subgenreReset"),
  boxes: await page.locator("#subgenreOptions input:checked").count(),
};
await clickReset("subgenreReset"); // clear them
report.subNone = {
  shows: await count(),
  chip: await chip("subgenre"),
  link: await resetText("subgenreReset"),
  boxes: await page.locator("#subgenreOptions input:checked").count(),
};

// ---- a partial subgenre selection must still narrow
const first = page.locator("#subgenreOptions input").first();
await first.check();
await page.waitForTimeout(500);
report.subOne = {
  value: await first.getAttribute("value"),
  shows: await count(),
  chip: await chip("subgenre"),
};

console.log(JSON.stringify(report, null, 2));
await browser.close();

