// Leaflet can't be fetched in this sandbox (unpkg blocked by the network
// policy), so stand in a permissive no-op `L` — enough for the Now page's map
// calls to be harmless while the real filter + list code runs on real data.
const handler = {
  get(target, prop) {
    if (prop === Symbol.toPrimitive) return () => 0;
    if (prop === "then") return undefined;
    if (!(prop in target)) target[prop] = makeStub();
    return target[prop];
  },
  apply() {
    return makeStub();
  },
};
function makeStub() {
  return new Proxy(function () {}, handler);
}
window.L = makeStub();

